#include <string>
#include <vector>

class Solution {
public:
    std::string findValidPair(std::string s) {
        std::vector<int> counts(10, 0);
        for (char c : s) {
            counts[c - '0']++;
        }
        for (size_t i = 0; i + 1 < s.length(); ++i) {
            int d1 = s[i] - '0';
            int d2 = s[i + 1] - '0';
            if (d1 != d2 && counts[d1] == d1 && counts[d2] == d2) {
                return s.substr(i, 2);
            }
        }
        return "";
    }
};

class Solution {
    public String findValidPair(String s) {
        int[] counts = new int[10];
        for (char c : s.toCharArray()) {
            counts[c - '0']++;
        }
        for (int i = 0; i < s.length() - 1; i++) {
            int d1 = s.charAt(i) - '0';
            int d2 = s.charAt(i + 1) - '0';
            if (d1 != d2 && counts[d1] == d1 && counts[d2] == d2) {
                return s.substring(i, i + 2);
            }
        }
        return "";
    }
}

var findValidPair = function(s) {
    const counts = new Int32Array(10);
    for (let i = 0; i < s.length; i++) {
        counts[s.charCodeAt(i) - 48]++;
    }
    for (let i = 0; i < s.length - 1; i++) {
        const d1 = s.charCodeAt(i) - 48;
        const d2 = s.charCodeAt(i + 1) - 48;
        if (d1 !== d2 && counts[d1] === d1 && counts[d2] === d2) {
            return s.slice(i, i + 2);
        }
    }
    return "";
